import { Breadcrumb } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { Card } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function BreadcrumbExample() {
  const [depth, setDepth] = useState(2),
    names = ['Projects', 'Library', 'Content guide'];
  return (
    <div style={stack}>
      <Breadcrumb
        items={names
          .slice(0, depth + 1)
          .map((label, i) => ({ label, onClick: () => setDepth(i) }))}
      />
      <Card>
        <h3>{names[depth]}</h3>
        {depth < 2 ? (
          <Button onClick={() => setDepth(depth + 1)}>Open {names[depth + 1]}</Button>
        ) : (
          <p>Content of the selected guide.</p>
        )}
      </Card>
    </div>
  );
}
export function Example() {
  return <BreadcrumbExample />;
}
